// Weekly Summary — Discord #weekly-summary with sprint velocity + improvements
const SK = $env.SUPABASE_SERVICE_ROLE_KEY;
const SUPA = '${NEXT_PUBLIC_SUPABASE_URL}';
const h = { apikey: SK, Authorization: 'Bearer ' + SK };
const DISCORD_TOKEN = 'MTQ4NjA0MTQ3MTUwNDM1MTMxMw.GoiBGW.VS2nGK2X1LMjMjkOBL9NqrOVeUdZfbGo9HdAyo';
const CHANNEL = '1488968230952239114'; // #weekly-summary
const MC_API = 'http://localhost:3000/api/issues';

const now = new Date();
const sevenDaysAgo = new Date(now - 7 * 24 * 60 * 60 * 1000).toISOString();
const weekStr = now.toLocaleDateString('en-US', {month:'long', day:'numeric', timeZone:'America/New_York'});

// Fetch data in parallel
const [allIssues, sprints] = await Promise.all([
  helpers.httpRequest({ method:'GET', url: MC_API, headers: h }),
  helpers.httpRequest({ method:'GET', url: SUPA+'/rest/v1/sprint_metrics?order=created_at.desc&limit=2', headers: h }).catch(()=>[])
]);

// Shipped this week (closed/completed/released in last 7 days)
const shipped = allIssues.filter(i =>
  ['closed','completed','released'].includes(i.status) &&
  i.completed_at && i.completed_at > sevenDaysAgo
);

// Top priorities next week
const nextUp = allIssues.filter(i =>
  ['open','backlog'].includes(i.status) &&
  ['critical','high'].includes(i.priority) &&
  !i.title.includes('MANUAL')
).slice(0,5);

// In progress now
const inProgress = allIssues.filter(i => i.status === 'in_progress');

// Blockers
const blocked = allIssues.filter(i => i.is_blocked || (i.blocked_by && i.status !== 'closed'));

// Code review queue
const codeReview = allIssues.filter(i => i.status === 'code_review');

// Sprint velocity from sprint_metrics table
let velocityLine = '';
if (sprints && sprints.length > 0) {
  const latest = sprints[0];
  velocityLine = `\n**📈 Sprint Velocity (Sprint ${latest.sprint_name || sprints[0].sprint_id?.slice(0,8)}):** ${latest.issues_closed}/${latest.issues_total || '?'} (${latest.velocity_pct || '?'}%)`;
  if (sprints[1]) velocityLine += ` · Prev: ${sprints[1].issues_closed}/${sprints[1].issues_total || '?'}`;
} else {
  const closedThisWeek = shipped.length;
  velocityLine = `\n**📈 Sprint Velocity (est. 7d):** ${closedThisWeek} issues shipped`;
}

// By project
const byProject = {};
for (const i of shipped) { byProject[i.project] = (byProject[i.project]||0)+1; }
const projBreakdown = Object.entries(byProject).map(([p,c]) => `${p}: ${c}`).join(' · ') || 'none';

// Agent throughput (issues shipped per agent)
const byAgent = {};
for (const i of shipped) { if(i.worked_by) byAgent[i.worked_by] = (byAgent[i.worked_by]||0)+1; }
const topAgents = Object.entries(byAgent).sort((a,b)=>b[1]-a[1]).slice(0,3).map(([a,c])=>`${a}(${c})`).join(', ');

// PRs merged this week
const prsThisWeek = allIssues.filter(i => i.pr_url && i.released_at && i.released_at > sevenDaysAgo).length;

let msg = `📊 **Weekly Summary — ${weekStr}**`;
msg += `\n${velocityLine}`;
msg += `\n\n**✅ Shipped (${shipped.length}):** ${projBreakdown}`;
if (topAgents) msg += `\n**🤖 Top Agents:** ${topAgents}`;
if (prsThisWeek) msg += `\n**🔀 PRs Merged:** ${prsThisWeek}`;
msg += `\n\n**🔧 In Progress (${inProgress.length}):**`;
inProgress.slice(0,3).forEach(i => msg += `\n  • ${i.task_key} ${i.title.slice(0,50)} _[${i.assignee}]_`);
if (!inProgress.length) msg += ' none';
msg += `\n\n**⏳ Code Review Queue:** ${codeReview.length} waiting`;
if (blocked.length) msg += `\n**🚫 Blocked:** ${blocked.length} issues`;
msg += `\n\n**🎯 Top Next Priorities:**`;
nextUp.slice(0,5).forEach(i => msg += `\n  • ${i.task_key} ${i.title.slice(0,50)} _[${i.priority}]_`);
msg += `\n\n📊 [Mission Control](https://kaos.nabit.work)`;

await helpers.httpRequest({
  method: 'POST',
  url: 'https://discord.com/api/v10/channels/' + CHANNEL + '/messages',
  headers: { Authorization: 'Bot ' + DISCORD_TOKEN, 'Content-Type': 'application/json' },
  body: JSON.stringify({ content: msg })
});

return [{ json: { shipped: shipped.length, velocity: velocityLine } }];
